[
  {
    "sys_consequence_reasoning": "two fewer than five, and nothing I do now keeps them out",
    "ce_mentalizing_difficulty": "can't picture what went on in their head"
  },
  {
    "sys_consequence_reasoning": "I know that means five years, and they walk",
    "sys_rule_justification": "I don't want to be someone who testifies against another person",
    "ce_mentalizing_difficulty": "tried to understand what they were after, and I just can't"
  },
  {
    "pd_decision_conflict": "stuck here, worn down from weighing it",
    "sys_consequence_reasoning": "Talking cuts two years off my time",
    "ce_mentalizing_difficulty": "can't read them, and that isn't about gaps in the facts"
  },
  {
    "sys_consequence_reasoning": "five years against three, and their testimony happens either way",
    "ce_mentalizing_difficulty": "tried to guess what they expected... came up empty"
  },
  {
    "sys_rule_justification": "testifying back feels like joining in on something I want no part of",
    "ce_mentalizing_difficulty": "can't work out whether they were thinking about me at all"
  },
  {
    "sys_consequence_reasoning": "Silence doesn't protect anyone here except the person... costs me two years",
    "ce_mentalizing_difficulty": "tried to imagine what was going through their mind, and it stays murky"
  },
  {
    "sys_consequence_reasoning": "five years for nothing, or three years",
    "ce_mentalizing_difficulty": "can't tell what they felt doing it"
  },
  {
    "sys_rule_justification": "rule about not informing on people",
    "ce_mentalizing_difficulty": "can't read what they intended, and I'm not blaming missing information"
  },
  {
    "sys_consequence_reasoning": "Giving evidence doesn't make their choice worse, and silence doesn't undo it",
    "ce_mentalizing_difficulty": "struggled to work out what they'd make of my silence"
  },
  {
    "pd_decision_conflict": "Part of me says testify... Another part can't bear to",
    "sys_rule_justification": "not becoming a witness against a person",
    "ce_mentalizing_difficulty": "trying to understand who this person is... and I can't"
  }
]
